import players

def solve(env):
    # dispatch to the per-level player for the current level, in a loop
    while not env.terminal():
        k = env.levels_completed + 1
        fn = getattr(players, f'play_level_{k}', None)
        if fn is None:
            return
        before = env.levels_completed
        fn(env)
        if env.levels_completed <= before:
            return  # no progress -> stop
"""Source-free frame perception helpers for cracking.

This module is deliberately observational: it derives compact symbolic state
from `env.frame()` and `env.clone()` only. It is a cofibration-style scaffold:
raw pixels are embedded into a monotone tower of reusable observations
(components -> objects -> action deltas -> replay states). Candidate level
logic should be written against these quotients, then replay-validated by the
harness. No game source or prior solution history is read here.
"""
from collections import deque
from dataclasses import dataclass
from typing import Dict, Iterable, List, Optional, Sequence, Tuple

import numpy as np

UP, DOWN, LEFT, RIGHT, USE = 1, 2, 3, 4, 5
ACTIONS = (UP, DOWN, LEFT, RIGHT, USE)
DIRS = {UP: (-1, 0), DOWN: (1, 0), LEFT: (0, -1), RIGHT: (0, 1)}
ACTION_NAME = {UP: "UP", DOWN: "DOWN", LEFT: "LEFT", RIGHT: "RIGHT", USE: "USE"}


@dataclass(frozen=True)
class Blob:
    color: int
    bbox: Tuple[int, int, int, int]  # r0, c0, r1, c1 inclusive
    area: int
    centroid: Tuple[float, float]

    @property
    def top_left(self):
        return self.bbox[0], self.bbox[1]

    @property
    def size(self):
        r0, c0, r1, c1 = self.bbox
        return r1 - r0 + 1, c1 - c0 + 1


def arr(frame) -> np.ndarray:
    return np.asarray(frame)


def color_counts(frame) -> Dict[int, int]:
    vals, cnts = np.unique(arr(frame), return_counts=True)
    return {int(v): int(c) for v, c in zip(vals, cnts)}


def connected_components(frame, colors: Optional[Iterable[int]] = None,
                         min_area: int = 1) -> List[Blob]:
    f = arr(frame)
    wanted = None if colors is None else {int(c) for c in colors}
    seen = np.zeros(f.shape, dtype=bool)
    out: List[Blob] = []
    rows, cols = f.shape[:2]
    for r in range(rows):
        for c in range(cols):
            if seen[r, c]:
                continue
            color = int(f[r, c])
            if wanted is not None and color not in wanted:
                seen[r, c] = True
                continue
            q = [(r, c)]
            seen[r, c] = True
            pts = []
            while q:
                x, y = q.pop()
                pts.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < rows and 0 <= ny < cols and not seen[nx, ny] and int(f[nx, ny]) == color:
                        seen[nx, ny] = True
                        q.append((nx, ny))
            if len(pts) >= min_area:
                rs = [p[0] for p in pts]
                cs = [p[1] for p in pts]
                out.append(Blob(color, (min(rs), min(cs), max(rs), max(cs)),
                                len(pts), (sum(rs) / len(pts), sum(cs) / len(pts))))
    return sorted(out, key=lambda b: (b.color, b.bbox))


def block_signatures(frame, cell: int = 4) -> Dict[Tuple[int, int], Tuple[int, ...]]:
    """Partition a frame into fixed cells and return each cell's color signature."""
    f = arr(frame)
    out = {}
    for r in range(0, f.shape[0], cell):
        for c in range(0, f.shape[1], cell):
            out[(r // cell, c // cell)] = tuple(int(v) for v in sorted(np.unique(f[r:r+cell, c:c+cell])))
    return out


def object_candidates(frame, cell: int = 4, min_area: int = 4) -> List[dict]:
    """A compact, game-agnostic object list from color components and cell signatures."""
    f = arr(frame)
    blobs = connected_components(f, min_area=min_area)
    sigs = block_signatures(f, cell)
    objects = []
    for b in blobs:
        r0, c0, r1, c1 = b.bbox
        objects.append({
            "color": b.color,
            "bbox": b.bbox,
            "top_left": b.top_left,
            "size": b.size,
            "area": b.area,
            "centroid": b.centroid,
            "cell": (r0 // cell, c0 // cell),
            "cell_sig": sigs.get((r0 // cell, c0 // cell)),
        })
    return objects


def frame_delta(before, after) -> dict:
    a, b = arr(before), arr(after)
    ys, xs = np.where(a != b)
    if len(ys) == 0:
        return {"count": 0, "bbox": None, "samples": []}
    samples = [(int(y), int(x), int(a[y, x]), int(b[y, x])) for y, x in zip(ys[:80], xs[:80])]
    return {
        "count": int(len(ys)),
        "bbox": (int(ys.min()), int(xs.min()), int(ys.max()), int(xs.max())),
        "samples": samples,
    }


def normalize_public_action(action):
    """Validate one public key or coordinate action without touching ``env``."""
    if isinstance(action, (list, tuple)):
        if (
            len(action) != 3
            or action[0] != 6
            or any(
                not isinstance(value, int) or isinstance(value, bool)
                for value in action
            )
        ):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        normalized = (6, int(action[1]), int(action[2]))
        if not (0 <= normalized[1] < 64 and 0 <= normalized[2] < 64):
            raise ValueError(
                "coordinate action must be (6, x, y) with integer x,y in 0..63"
            )
        return normalized
    if (
        not isinstance(action, int)
        or isinstance(action, bool)
        or action not in range(1, 8)
    ):
        raise ValueError("key action must be an integer in 1..7")
    if action == 6:
        raise ValueError(
            "bare ACTION6 is invalid; use (6, x, y) with integer x,y in 0..63"
        )
    return int(action)


def safe_step(env, action):
    """Validate locally, then apply one public key or coordinate action."""
    normalized = normalize_public_action(action)
    if isinstance(normalized, tuple):
        env.step(*normalized)
    else:
        env.step(normalized)
    return normalized


def action_deltas(env, actions=None) -> Dict[object, dict]:
    """Compare valid cloned actions; bare ACTION6 is never sent to the arena."""
    if actions is None:
        actions = tuple(action for action in env.actions if action != 6)
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    base = arr(env.frame()).copy()
    out = {}
    for action in normalized_actions:
        clone = env.clone()
        safe_step(clone, action)
        out[action] = frame_delta(base, clone.frame())
    return out


def replay(env, actions: Sequence):
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    clone = env.clone()
    for action in normalized_actions:
        if clone.terminal():
            break
        safe_step(clone, action)
    return clone


def path_result(env, actions: Sequence[int]) -> dict:
    clone = replay(env, actions)
    return {
        "levels_completed": int(clone.levels_completed),
        "terminal": bool(clone.terminal()),
        "path_len": len(actions),
        "colors": color_counts(clone.frame()),
        "objects": object_candidates(clone.frame()),
    }


def changed_signature(env, actions: Sequence[int], cell: int = 4):
    before = block_signatures(env.frame(), cell)
    clone = replay(env, actions)
    after = block_signatures(clone.frame(), cell)
    return {k: (before.get(k), after.get(k)) for k in sorted(set(before) | set(after))
            if before.get(k) != after.get(k)}


def bounded_bfs(env, goal_fn, actions=None,
                key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """BFS over advertised key actions by default; use small bounds first."""
    if actions is None:
        actions = tuple(action for action in env.actions if action != 6)
    normalized_actions = tuple(
        normalize_public_action(action) for action in actions
    )
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()
    start_key = key_fn(env)
    q = deque([(env.clone(), [])])
    seen = {start_key}
    while q and len(seen) <= max_states:
        node, path = q.popleft()
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth:
            continue
        for action in normalized_actions:
            child = node.clone()
            normalized = safe_step(child, action)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            q.append((child, path + [normalized]))
    return None


def bounded_replay_bfs(env, goal_fn, action_fn,
                       key_fn=None, max_states: int = 20000, max_depth: int = 80):
    """Path-only BFS for games whose deep Arena clones become expensive.

    The queue retains compact action paths, not recursively deep-copied runtime
    states. Each node is reconstructed from one root clone. ``action_fn(node)``
    may return integer actions or coordinate tuples such as ``(6, x, y)``.
    """
    if key_fn is None:
        key_fn = lambda e: arr(e.frame()).tobytes()

    def reconstruct(path):
        node = env.clone()
        for action in path:
            safe_step(node, action)
        return node

    start = reconstruct([])
    q = deque([[]])
    seen = {key_fn(start)}
    while q and len(seen) <= max_states:
        path = q.popleft()
        node = reconstruct(path)
        if goal_fn(node, path):
            return path
        if len(path) >= max_depth or node.terminal():
            continue
        actions = tuple(
            normalize_public_action(action)
            for action in action_fn(node)
        )
        for action in actions:
            child_path = path + [action]
            child = reconstruct(child_path)
            key = key_fn(child)
            if key in seen:
                continue
            seen.add(key)
            if goal_fn(child, child_path):
                return child_path
            q.append(child_path)
    return None


def level_goal(base_level: int):
    return lambda env, path: env.levels_completed > base_level

# Shared leg library: small, named, reusable skills.
# Players import from here; add a NEW leg only when no existing leg fits.

from collections import deque
from heapq import heappop, heappush
from math import gcd

from perception import arr, connected_components


def play_action(env, action):
    """Execute one key action or coordinate-click action."""
    if isinstance(action, tuple):
        env.step(*action)
    else:
        env.step(action)


def play_actions(env, actions):
    """Execute key and coordinate-click actions in order."""
    for action in actions:
        play_action(env, action)


def play_lattice_moves(env, moves):
    """Execute source/destination moves on the visible slot lattice."""
    for source, destination in moves:
        play_actions(env, (
            (6, source[1] + 1, source[0] + 1),
            (6, destination[1] + 1, destination[0] + 1),
        ))


def _peg_board(frame):
    """Return the slot lattice and occupied slots visible in a peg board."""
    holes = {
        blob.top_left
        for blob in connected_components(frame, colors=(1,))
        if blob.size == (4, 4) and blob.area == 16
    }
    pegs = {
        blob.top_left
        for blob in connected_components(frame, colors=(14,))
        if blob.size == (4, 4)
    }
    return holes | pegs, frozenset(pegs)


def _lattice_step(slots):
    coordinates = [
        sorted({position[axis] for position in slots})
        for axis in (0, 1)
    ]
    differences = [
        later - earlier
        for values in coordinates
        for earlier, later in zip(values, values[1:])
        if later > earlier
    ]
    step = 0
    for difference in differences:
        step = gcd(step, difference)
    return step


def _peg_solution(slots, start):
    """Find captures that leave the confirmed winning state of one peg."""
    step = _lattice_step(slots)
    if not step:
        return None
    queue = deque([(start, ())])
    seen = {start}
    directions = ((-step, 0), (step, 0), (0, -step), (0, step))
    while queue:
        pegs, path = queue.popleft()
        if len(pegs) == 1:
            return path
        for source in sorted(pegs):
            for dr, dc in directions:
                jumped = (source[0] + dr, source[1] + dc)
                destination = (source[0] + 2 * dr, source[1] + 2 * dc)
                if (
                    jumped in pegs
                    and destination in slots
                    and destination not in pegs
                ):
                    child = frozenset((pegs - {source, jumped}) | {destination})
                    if child not in seen:
                        seen.add(child)
                        queue.append((child, path + ((source, destination),)))
    return None


def solve_peg_solitaire(env):
    """Solve a visible orthogonal peg-solitaire board using coordinate clicks."""
    slots, pegs = _peg_board(env.frame())
    solution = _peg_solution(slots, pegs)
    if solution is None:
        return
    play_lattice_moves(env, solution)


def _carrier_capture_macros(frame):
    """Return visible peg captures, including an empty bordered carrier."""
    slots, pegs = _peg_board(frame)
    carriers = {
        blob.top_left
        for blob in connected_components(frame, colors=(12,))
        if blob.size == (4, 4)
    }
def solve_peg_solitaire_with_carrier(env, max_states=2000, max_depth=40):
    """Solve peg boards connected by a key-movable bordered carrier slot."""
    base_level = env.levels_completed

    def key(node):
        frame = arr(node.frame())
        return int(node.levels_completed), frame[1:, :].tobytes()

    queue = deque([(env.clone(), ())])
    seen = {key(env)}
    solution = None
    while queue and len(seen) < max_states:
        node, path = queue.popleft()
        if len(path) >= max_depth:
            continue
        macros = tuple((action,) for action in (1, 2, 3, 4))
        macros += _carrier_capture_macros(node.frame())
        for macro in macros:
            child = node.clone()
            for action in macro:
                play_action(child, action)
                if child.levels_completed > base_level:
                    solution = path + (macro,)
                    break
            if solution is not None:
                queue.clear()
                break
            child_key = key(child)
            if child_key not in seen:
                seen.add(child_key)
                queue.append((child, path + (macro,)))

    if solution is None:
        return
    for macro in solution:
        play_actions(env, macro)


def _bridge_carrier_state(frame):
    """Return the puzzle-relevant geometry of a bridge/carrier peg board."""
    blobs = connected_components(
        frame, colors=(1, 3, 11, 12, 14, 15)
    )
    slots = {
        blob.top_left
        for blob in blobs
        if blob.color == 1 and blob.size == (4, 4) and blob.area == 16
    }
    pegs = {
        blob.top_left
        for blob in blobs
        if blob.color == 14 and blob.size == (4, 4)
    }
    slots |= {
        (blob.bbox[0] - 1, blob.bbox[1] - 1)
        for blob in blobs
        if blob.color == 1 and blob.size == (2, 2) and blob.area == 4
    }
    carriers = frozenset(
        (
            (blob.bbox[0] - 1, blob.bbox[1] - 1)
            if blob.size == (2, 2) else blob.top_left
        )
        for blob in blobs
        if blob.color == 12 and blob.size in ((2, 2), (4, 4))
    )
    bridges = frozenset(
        (blob.bbox[0] + 1, blob.bbox[1])
        for blob in blobs
        if blob.color == 15 and blob.size == (4, 4)
    )
    borders = frozenset(
        blob.top_left
        for blob in blobs
        if blob.color == 11 and blob.area >= 4
    )
    selected_blobs = [
        blob for blob in blobs
        if blob.color == 3 and blob.area >= 4
    ]
    selected = (
        (selected_blobs[0].bbox[0] + 1, selected_blobs[0].bbox[1] + 1)
        if selected_blobs else None
    )
    return (
        frozenset(slots), frozenset(pegs), carriers,
        bridges, borders, selected,
    )


def _bridge_carrier_moves_from_state(state):
    slots, pegs, carriers, bridges, _, _ = state
    step = _lattice_step(slots | carriers)
    if not step:
        return ()
    moves = []
    destinations = slots | carriers
    for source in sorted(pegs):
        for dr, dc in ((-step, 0), (step, 0), (0, -step), (0, step)):
            midpoint = (source[0] + dr, source[1] + dc)
            destination = (source[0] + 2 * dr, source[1] + 2 * dc)
            if destination not in destinations or destination in pegs:
                continue
            if midpoint in pegs:
                moves.append(("capture", source, destination))
            elif midpoint in bridges:
                moves.append(("bridge", source, destination))
    return tuple(moves)


def _bridge_carrier_moves(frame):
    """Return legal (kind, source, destination) peg moves."""
    return _bridge_carrier_moves_from_state(_bridge_carrier_state(frame))


def solve_bridge_carrier_peg_solitaire(
        env, max_align_states=120, max_macros=40, alignment_lookahead=24):
    """Solve peg boards joined by persistent bridges and a movable carrier."""
    base_level = env.levels_completed
def _movable_bridge_board(frame):
    """Return visible slots, carriers, movable bridges, and pegs."""
    blobs = connected_components(frame, colors=(1, 8, 12, 14))
    slots = {
        blob.top_left
        for blob in blobs
        if blob.color == 1 and blob.size == (4, 4) and blob.area == 16
    }
    carriers = {
        blob.top_left
        for blob in blobs
        if blob.color == 12 and blob.size == (4, 4)
    }
    bridges = {
        blob.top_left
        for blob in blobs
        if blob.color == 8 and blob.size == (4, 4)
    }
    pegs = {
        blob.top_left
        for blob in blobs
        if blob.color == 14 and blob.size == (4, 4)
    }
    return slots, carriers, bridges, pegs


def _movable_bridge_solution(frame, max_states=20000):
    """Solve a visible relay board containing one reusable movable bridge."""
    slots, carriers, bridges, pegs = _movable_bridge_board(frame)
    if len(bridges) != 1:
        return None
    start = (frozenset(pegs), next(iter(bridges)))
    queue = deque([(start, ())])
    seen = {start}
    destinations = slots | carriers
    while queue and len(seen) <= max_states:
        (state_pegs, bridge), path = queue.popleft()
        if len(state_pegs) == 1 and next(iter(state_pegs)) in carriers:
            return path
        occupied = state_pegs | {bridge}
        pieces = tuple(("peg", peg) for peg in sorted(state_pegs))
        pieces += (("bridge", bridge),)
        for kind, source in pieces:
            for dr, dc in ((-6, 0), (6, 0), (0, -6), (0, 6)):
                midpoint = (source[0] + dr, source[1] + dc)
                destination = (source[0] + 2 * dr, source[1] + 2 * dc)
                if (
                    destination not in destinations
                    or destination in occupied
                    or midpoint not in occupied
                    or (kind == "bridge" and midpoint not in state_pegs)
                ):
                    continue
                child_pegs = set(state_pegs)
                child_bridge = bridge
                if kind == "bridge":
                    child_bridge = destination
                else:
                    child_pegs.remove(source)
                    child_pegs.add(destination)
                    if midpoint in child_pegs:
                        child_pegs.remove(midpoint)
                child = (frozenset(child_pegs), child_bridge)
                if child not in seen:
                    seen.add(child)
                    queue.append((child, path + ((source, destination),)))
    return None


def solve_wrapped_bridge_carrier_peg_solitaire(env):
    """Solve a long relay whose carrier rails reveal successive peg regions."""
    local_solution = _movable_bridge_solution(env.frame())
    if local_solution is None:
        return
    play_lattice_moves(env, local_solution)

    _, carriers, bridges, _ = _movable_bridge_board(env.frame())
    if len(carriers) != 1 or len(bridges) != 1:
        return
    play_lattice_moves(env, ((next(iter(bridges)), next(iter(carriers))),))

    play_actions(env, (4,) * 9 + (1, 1, 3, 3, 1, 1))

