        if coordinate_actions >= 2 * completed_macros:
            break
        safe_step(env, action)
        if isinstance(action, list):
            coordinate_actions += 1

    root = env.clone()
    max_depth = int(os.environ.get("MAX_DEPTH", "12"))
    max_states = int(os.environ.get("MAX_STATES", "500"))
    root_key = state_key(root)
    queue = deque([()])
    seen = {root_key}
    options = {}
    while queue and len(seen) <= max_states:
        path = queue.popleft()
        for action in path:
            safe_step(root, action)
        for move in candidate_moves(root.frame()):
            options.setdefault(move, path)
        if len(path) >= max_depth:
            for _ in path:
                safe_step(root, 7)
            continue
        for action in KEYS:
            before_key = state_key(root)
            safe_step(root, action)
            key = state_key(root)
            if key not in seen:
                seen.add(key)
                queue.append(path + (action,))
            if key != before_key:
                safe_step(root, 7)
        for _ in path:
            safe_step(root, 7)
        if state_key(root) != root_key:
            raise RuntimeError("undo traversal failed to restore root")

    print("OPTION_SEARCH", {"bridge_first": bridge_first,
                            "after_macros": completed_macros,
                            "states": len(seen), "remaining": len(queue),
                            "max_depth": max_depth})
    for move, path in sorted(options.items(), key=lambda item:
                             (len(item[1]), item[0])):
        print("OPTION", {"keys": path, "move": move})


